"""Insert spec for auto-generated file revisions."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass
from typing import override

import sqlalchemy as sa

from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
from ai.backend.common.data.entity.auto_generated_file_revision import AutoGeneratedFileRevisionID
from ai.backend.manager.data.auto_generated_file.types import (
    AutoGeneratedFileRevisionData,
    AutoGeneratedFileRevisionSpec,
)
from ai.backend.manager.models.auto_generated_file_revision.row import AutoGeneratedFileRevisionRow
from ai.backend.manager.models.auto_generated_file_revision.searchable_fields import (
    AutoGeneratedFileRevisionSearchableFields,
)
from ai.backend.manager.models.specs.creator import FieldCreator
from ai.backend.manager.models.specs.types import IntegrityErrorCheck


@dataclass
class AutoGeneratedFileRevisionCreator(
    FieldCreator[AutoGeneratedFileID, AutoGeneratedFileRevisionRow, AutoGeneratedFileRevisionData]
):
    """The next revision of a file's content."""

    revision: AutoGeneratedFileRevisionSpec

    @override
    def build_row(self, owner_id: AutoGeneratedFileID) -> AutoGeneratedFileRevisionRow:
        return AutoGeneratedFileRevisionRow(
            file_id=owner_id,
            revision_number=(
                sa.select(
                    sa.func.coalesce(sa.func.max(AutoGeneratedFileRevisionRow.revision_number), 0)
                    + 1
                )
                .where(AutoGeneratedFileRevisionRow.file_id == owner_id)
                .scalar_subquery()
            ),
            data=self.revision.data,
            perm=self.revision.perm,
            creator_id=self.revision.creator_id,
        )

    @override
    def field_id(self, row: AutoGeneratedFileRevisionRow) -> AutoGeneratedFileRevisionID:
        return row.id

    @override
    def integrity_error_checks(self) -> Sequence[IntegrityErrorCheck]:
        return ()

    @override
    def to_data(self, row: AutoGeneratedFileRevisionRow) -> AutoGeneratedFileRevisionData:
        return AutoGeneratedFileRevisionSearchableFields.own.to_data(row)
